-- 048: профили типов кузова, поля и параметры (specs) у машин и грузов.
CREATE TYPE "BodyTypeProfile" AS ENUM ('VOLUME', 'PLATFORM', 'CONTAINER', 'BULK', 'TANK', 'CAR_CARRIER');
ALTER TABLE "body_types" ADD COLUMN "profile" "BodyTypeProfile" NOT NULL DEFAULT 'VOLUME', ADD COLUMN "fields" JSONB NOT NULL DEFAULT '[]';
ALTER TABLE "vehicles" ADD COLUMN "specs" JSONB;
ALTER TABLE "drivers" ADD COLUMN "preferredSpecs" JSONB;
ALTER TABLE "cargos" ADD COLUMN "extraBodyTypeIds" TEXT[] DEFAULT ARRAY[]::TEXT[], ADD COLUMN "specs" JSONB;

-- Профиль и поля существующим типам (дальше админ правит без релиза).
UPDATE "body_types" SET "profile" = 'VOLUME', "fields" = '[{"key":"capacityTons","kind":"number","unit":"t","label":{"kk":"Жүккөтергіштігі","ru":"Грузоподъёмность","zh":"载重","en":"Payload"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"min":0.5,"max":80},{"key":"volumeM3","kind":"number","unit":"m3","label":{"kk":"Шанақ көлемі","ru":"Объём кузова","zh":"车厢容积","en":"Body volume"},"forVehicle":true,"forCargo":false,"min":1,"max":200},{"key":"palletsEuro","kind":"number","unit":"pallets","label":{"kk":"Еуропаллеттер","ru":"Европаллеты","zh":"欧标托盘","en":"Euro pallets"},"forVehicle":true,"forCargo":false,"min":1,"max":60},{"key":"innerLengthM","kind":"number","unit":"m","label":{"kk":"Шанақ ұзындығы","ru":"Длина кузова","zh":"车厢长度","en":"Body length"},"forVehicle":true,"forCargo":false,"min":1,"max":20},{"key":"innerWidthM","kind":"number","unit":"m","label":{"kk":"Шанақ ені","ru":"Ширина кузова","zh":"车厢宽度","en":"Body width"},"forVehicle":true,"forCargo":false,"min":1,"max":4},{"key":"innerHeightM","kind":"number","unit":"m","label":{"kk":"Шанақ биіктігі","ru":"Высота кузова","zh":"车厢高度","en":"Body height"},"forVehicle":true,"forCargo":false,"min":1,"max":4.5}]'::jsonb WHERE "code" = 'TENT';
