UPDATE "body_types" SET "profile" = 'VOLUME', "fields" = '[{"key":"capacityTons","kind":"number","unit":"t","label":{"kk":"Жүккөтергіштігі","ru":"Грузоподъёмность","zh":"载重","en":"Payload"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"min":0.5,"max":80},{"key":"volumeM3","kind":"number","unit":"m3","label":{"kk":"Шанақ көлемі","ru":"Объём кузова","zh":"车厢容积","en":"Body volume"},"forVehicle":true,"forCargo":false,"min":1,"max":200},{"key":"palletsEuro","kind":"number","unit":"pallets","label":{"kk":"Еуропаллеттер","ru":"Европаллеты","zh":"欧标托盘","en":"Euro pallets"},"forVehicle":true,"forCargo":false,"min":1,"max":60},{"key":"innerLengthM","kind":"number","unit":"m","label":{"kk":"Шанақ ұзындығы","ru":"Длина кузова","zh":"车厢长度","en":"Body length"},"forVehicle":true,"forCargo":false,"min":1,"max":20},{"key":"innerWidthM","kind":"number","unit":"m","label":{"kk":"Шанақ ені","ru":"Ширина кузова","zh":"车厢宽度","en":"Body width"},"forVehicle":true,"forCargo":false,"min":1,"max":4},{"key":"innerHeightM","kind":"number","unit":"m","label":{"kk":"Шанақ биіктігі","ru":"Высота кузова","zh":"车厢高度","en":"Body height"},"forVehicle":true,"forCargo":false,"min":1,"max":4.5},{"key":"tempMin","kind":"number","unit":"c","label":{"kk":"Температура бастап","ru":"Температура от","zh":"最低温度","en":"Temperature from"},"forVehicle":true,"forCargo":false,"primary":true,"min":-30,"max":25},{"key":"tempMax","kind":"number","unit":"c","label":{"kk":"Температура дейін","ru":"Температура до","zh":"最高温度","en":"Temperature to"},"forVehicle":true,"forCargo":false,"min":-30,"max":25},{"key":"tempRequired","kind":"number","unit":"c","label":{"kk":"Қажетті температура","ru":"Нужная температура","zh":"所需温度","en":"Required temperature"},"forVehicle":false,"forCargo":true,"min":-30,"max":25}]'::jsonb WHERE "code" = 'REFRIGERATOR';
UPDATE "body_types" SET "profile" = 'PLATFORM', "fields" = '[{"key":"capacityTons","kind":"number","unit":"t","label":{"kk":"Жүккөтергіштігі","ru":"Грузоподъёмность","zh":"载重","en":"Payload"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"min":0.5,"max":80},{"key":"platformLengthM","kind":"number","unit":"m","label":{"kk":"Платформа ұзындығы","ru":"Длина платформы","zh":"平台长度","en":"Platform length"},"forVehicle":true,"forCargo":false,"min":3,"max":25},{"key":"cargoLengthM","kind":"number","unit":"m","label":{"kk":"Жүк ұзындығы","ru":"Длина груза","zh":"货物长度","en":"Cargo length"},"forVehicle":false,"forCargo":true,"min":0.1,"max":40},{"key":"cargoWidthM","kind":"number","unit":"m","label":{"kk":"Жүк ені","ru":"Ширина груза","zh":"货物宽度","en":"Cargo width"},"forVehicle":false,"forCargo":true,"min":0.1,"max":10},{"key":"cargoHeightM","kind":"number","unit":"m","label":{"kk":"Жүк биіктігі","ru":"Высота груза","zh":"货物高度","en":"Cargo height"},"forVehicle":false,"forCargo":true,"min":0.1,"max":10},{"key":"oversize","kind":"bool","label":{"kk":"Габаритсіз","ru":"Негабарит","zh":"超限","en":"Oversize"},"forVehicle":false,"forCargo":true}]'::jsonb WHERE "code" = 'FLATBED';
UPDATE "body_types" SET "profile" = 'PLATFORM', "fields" = '[{"key":"capacityTons","kind":"number","unit":"t","label":{"kk":"Жүккөтергіштігі","ru":"Грузоподъёмность","zh":"载重","en":"Payload"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"min":0.5,"max":80},{"key":"platformLengthM","kind":"number","unit":"m","label":{"kk":"Платформа ұзындығы","ru":"Длина платформы","zh":"平台长度","en":"Platform length"},"forVehicle":true,"forCargo":false,"min":3,"max":25},{"key":"deckHeightM","kind":"number","unit":"m","label":{"kk":"Алаң биіктігі","ru":"Высота площадки","zh":"平台高度","en":"Deck height"},"forVehicle":true,"forCargo":false,"min":0.2,"max":2},{"key":"oversizeAllowed","kind":"bool","label":{"kk":"Габаритсізге рұқсат","ru":"Допуск на негабарит","zh":"可运超限","en":"Oversize permit"},"forVehicle":true,"forCargo":false},{"key":"cargoLengthM","kind":"number","unit":"m","label":{"kk":"Жүк ұзындығы","ru":"Длина груза","zh":"货物长度","en":"Cargo length"},"forVehicle":false,"forCargo":true,"min":0.1,"max":40},{"key":"cargoWidthM","kind":"number","unit":"m","label":{"kk":"Жүк ені","ru":"Ширина груза","zh":"货物宽度","en":"Cargo width"},"forVehicle":false,"forCargo":true,"min":0.1,"max":10},{"key":"cargoHeightM","kind":"number","unit":"m","label":{"kk":"Жүк биіктігі","ru":"Высота груза","zh":"货物高度","en":"Cargo height"},"forVehicle":false,"forCargo":true,"min":0.1,"max":10},{"key":"oversize","kind":"bool","label":{"kk":"Габаритсіз","ru":"Негабарит","zh":"超限","en":"Oversize"},"forVehicle":false,"forCargo":true}]'::jsonb WHERE "code" = 'LOWLOADER';
UPDATE "body_types" SET "profile" = 'CONTAINER', "fields" = '[{"key":"containerTypes","kind":"multi","label":{"kk":"Контейнерлер","ru":"Контейнеры","zh":"集装箱类型","en":"Containers"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"options":[{"code":"20","label":{"kk":"20''","ru":"20''","zh":"20''","en":"20''"}},{"code":"40","label":{"kk":"40''","ru":"40''","zh":"40''","en":"40''"}},{"code":"45","label":{"kk":"45''","ru":"45''","zh":"45''","en":"45''"}}]},{"key":"slots","kind":"number","unit":"slots","label":{"kk":"Контейнер орындары","ru":"Мест под контейнеры","zh":"箱位数","en":"Container slots"},"forVehicle":true,"forCargo":false,"min":1,"max":4},{"key":"containerType","kind":"enum","label":{"kk":"Контейнер түрі","ru":"Тип контейнера","zh":"集装箱类型","en":"Container type"},"forVehicle":false,"forCargo":true,"required":true,"options":[{"code":"20","label":{"kk":"20''","ru":"20''","zh":"20''","en":"20''"}},{"code":"40","label":{"kk":"40''","ru":"40''","zh":"40''","en":"40''"}},{"code":"45","label":{"kk":"45''","ru":"45''","zh":"45''","en":"45''"}}]},{"key":"containerCount","kind":"number","unit":"slots","label":{"kk":"Саны","ru":"Количество","zh":"数量","en":"Count"},"forVehicle":false,"forCargo":true,"min":1,"max":4}]'::jsonb WHERE "code" = 'CONTAINER';
UPDATE "body_types" SET "profile" = 'BULK', "fields" = '[{"key":"capacityTons","kind":"number","unit":"t","label":{"kk":"Жүккөтергіштігі","ru":"Грузоподъёмность","zh":"载重","en":"Payload"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"min":0.5,"max":80},{"key":"bodyVolumeM3","kind":"number","unit":"m3","label":{"kk":"Шанақ көлемі","ru":"Объём кузова","zh":"车厢容积","en":"Body volume"},"forVehicle":true,"forCargo":false,"min":1,"max":150}]'::jsonb WHERE "code" = 'DUMP';
UPDATE "body_types" SET "profile" = 'BULK', "fields" = '[{"key":"capacityTons","kind":"number","unit":"t","label":{"kk":"Жүккөтергіштігі","ru":"Грузоподъёмность","zh":"载重","en":"Payload"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"min":0.5,"max":80},{"key":"bodyVolumeM3","kind":"number","unit":"m3","label":{"kk":"Шанақ көлемі","ru":"Объём кузова","zh":"车厢容积","en":"Body volume"},"forVehicle":true,"forCargo":false,"min":1,"max":150}]'::jsonb WHERE "code" = 'GRAIN';
UPDATE "body_types" SET "profile" = 'TANK', "fields" = '[{"key":"liters","kind":"number","unit":"l","label":{"kk":"Цистерна көлемі","ru":"Объём цистерны","zh":"罐容","en":"Tank volume"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"min":1000,"max":60000},{"key":"product","kind":"enum","label":{"kk":"Өнім","ru":"Продукт","zh":"介质","en":"Product"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"options":[{"code":"FUEL","label":{"kk":"Жанармай","ru":"Топливо","zh":"燃油","en":"Fuel"}},{"code":"FOOD","label":{"kk":"Азық-түлік","ru":"Пищевое","zh":"食品级","en":"Food grade"}},{"code":"CHEMICAL","label":{"kk":"Химия","ru":"Химия","zh":"化学品","en":"Chemicals"}},{"code":"GAS","label":{"kk":"Газ","ru":"Газ","zh":"气体","en":"Gas"}}]},{"key":"sections","kind":"number","unit":"sections","label":{"kk":"Секциялар","ru":"Секции","zh":"仓数","en":"Compartments"},"forVehicle":true,"forCargo":false,"min":1,"max":8},{"key":"cargoProduct","kind":"enum","label":{"kk":"Өнім","ru":"Продукт","zh":"介质","en":"Product"},"forVehicle":false,"forCargo":true,"required":true,"options":[{"code":"FUEL","label":{"kk":"Жанармай","ru":"Топливо","zh":"燃油","en":"Fuel"}},{"code":"FOOD","label":{"kk":"Азық-түлік","ru":"Пищевое","zh":"食品级","en":"Food grade"}},{"code":"CHEMICAL","label":{"kk":"Химия","ru":"Химия","zh":"化学品","en":"Chemicals"}},{"code":"GAS","label":{"kk":"Газ","ru":"Газ","zh":"气体","en":"Gas"}}]},{"key":"cargoLiters","kind":"number","unit":"l","label":{"kk":"Литр","ru":"Литров","zh":"升","en":"Liters"},"forVehicle":false,"forCargo":true,"required":true,"min":100,"max":60000}]'::jsonb WHERE "code" = 'TANK';
UPDATE "body_types" SET "profile" = 'CAR_CARRIER', "fields" = '[{"key":"carSlots","kind":"number","unit":"cars","label":{"kk":"Көлік орындары","ru":"Мест под машины","zh":"车位数","en":"Car slots"},"forVehicle":true,"forCargo":false,"required":true,"primary":true,"min":1,"max":12},{"key":"closed","kind":"bool","label":{"kk":"Жабық","ru":"Закрытый","zh":"封闭式","en":"Enclosed"},"forVehicle":true,"forCargo":false},{"key":"carCount","kind":"number","unit":"cars","label":{"kk":"Көлік","ru":"Машин","zh":"车辆数","en":"Cars"},"forVehicle":false,"forCargo":true,"required":true,"min":1,"max":12},{"key":"carType","kind":"enum","label":{"kk":"Көлік түрі","ru":"Тип авто","zh":"车型","en":"Car type"},"forVehicle":false,"forCargo":true,"options":[{"code":"PASSENGER","label":{"kk":"Жеңіл","ru":"Легковые","zh":"轿车","en":"Passenger cars"}},{"code":"SUV","label":{"kk":"Жол талғамайтын","ru":"Внедорожники","zh":"SUV","en":"SUVs"}},{"code":"MINIBUS","label":{"kk":"Шағын автобустар","ru":"Микроавтобусы","zh":"小型客车","en":"Minibuses"}}]}]'::jsonb WHERE "code" = 'CARCARRIER';

-- Объёмные: значения машин копируются в specs (колонки остаются проекцией для 033/037).
UPDATE "vehicles" v SET "specs" = jsonb_strip_nulls(jsonb_build_object('capacityTons', v."capacityTons", 'volumeM3', v."volumeM3", 'palletsEuro', v."palletsEuro", 'innerLengthM', v."innerLengthM", 'innerWidthM', v."innerWidthM", 'innerHeightM', v."innerHeightM"))
FROM "body_types" b WHERE b."id" = v."bodyTypeId" AND b."profile" = 'VOLUME';
-- Остальные: тоннаж — в specs, где он поле профиля; объём/паллеты/размер — обнулить.
UPDATE "vehicles" v SET "specs" = CASE WHEN b."profile" IN ('PLATFORM', 'BULK') AND v."capacityTons" IS NOT NULL THEN jsonb_build_object('capacityTons', v."capacityTons") ELSE NULL END,
  "volumeM3" = NULL, "palletsEuro" = NULL, "innerLengthM" = NULL, "innerWidthM" = NULL, "innerHeightM" = NULL, "sizePresetId" = NULL
FROM "body_types" b WHERE b."id" = v."bodyTypeId" AND b."profile" <> 'VOLUME';
